contracts/BridgeGuard.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title BridgedToken: a token that exists on ZETAPHY only through a bridge
/// @notice Only its BridgeGuard can mint (assets arriving) or burn (leaving).
contract BridgedToken {
    string public name;
    string public symbol;
    uint8 public immutable decimals;
    address public immutable guard;
    uint256 public totalSupply;
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);

    constructor(string memory n, string memory s, uint8 d, address guard_) {
        name = n; symbol = s; decimals = d; guard = guard_;
    }

    modifier onlyGuard() { require(msg.sender == guard, "only guard"); _; }

    function mint(address to, uint256 v) external onlyGuard { totalSupply += v; balanceOf[to] += v; emit Transfer(address(0), to, v); }
    function burn(address from, uint256 v) external onlyGuard {
        require(balanceOf[from] >= v, "balance");
        balanceOf[from] -= v; totalSupply -= v; emit Transfer(from, address(0), v);
    }
    function approve(address s, uint256 v) external returns (bool) { allowance[msg.sender][s] = v; emit Approval(msg.sender, s, v); return true; }
    function transfer(address to, uint256 v) external returns (bool) { _move(msg.sender, to, v); return true; }
    function transferFrom(address f, address to, uint256 v) external returns (bool) {
        uint256 a = allowance[f][msg.sender];
        if (a != type(uint256).max) { require(a >= v, "allowance"); allowance[f][msg.sender] = a - v; }
        _move(f, to, v); return true;
    }
    function _move(address f, address to, uint256 v) private {
        require(to != address(0) && balanceOf[f] >= v, "transfer");
        balanceOf[f] -= v; balanceOf[to] += v; emit Transfer(f, to, v);
    }
}

/// @title BridgeGuard: limits and a stop button for every bridge route (stage 3)
/// @notice A bridge adapter (Hyperlane warp route, IBC hook, ...) never mints
///         or burns directly: it asks this guard, which enforces
///           - a daily limit per route and direction, so a hacked bridge can
///             lose at most one day's limit, not everything;
///           - a pause that only guardians can pull and only governance can
///             release. Pausing stops the bridges, never the chain.
///         Governance should be the chain's gov module or a multisig.
contract BridgeGuard {
    struct Route {
        address adapter;      // the only caller allowed for this route
        uint128 dailyLimit;   // per direction, in token units
        uint128 inToday;
        uint128 outToday;
        uint64 day;
        bool enabled;
    }

    BridgedToken public token;
    address public governance;
    mapping(address => bool) public guardian;
    bool public paused;
    mapping(bytes32 => Route) public routes;

    event RouteSet(bytes32 indexed id, address adapter, uint128 dailyLimit, bool enabled);
    event GuardianSet(address indexed who, bool allowed);
    event Paused(address indexed by);
    event Unpaused();
    event Inbound(bytes32 indexed route, address indexed to, uint256 amount);
    event Outbound(bytes32 indexed route, address indexed from, uint256 amount);

    error NotGovernance();
    error NotGuardian();
    error NotAdapter();
    error BridgePaused();
    error OverLimit(uint256 remaining);

    constructor(address governance_) {
        governance = governance_;
    }

    /// One-time: the guard deploys and owns its token.
    function createToken(string calldata n, string calldata s, uint8 d) external returns (BridgedToken) {
        if (msg.sender != governance) revert NotGovernance();
        require(address(token) == address(0), "token exists");
        token = new BridgedToken(n, s, d, address(this));
        return token;
    }

    modifier onlyGov() { if (msg.sender != governance) revert NotGovernance(); _; }

    function setGovernance(address g) external onlyGov { governance = g; }
    function setGuardian(address who, bool allowed) external onlyGov { guardian[who] = allowed; emit GuardianSet(who, allowed); }

    function setRoute(bytes32 id, address adapter, uint128 dailyLimit, bool enabled) external onlyGov {
        Route storage r = routes[id];
        r.adapter = adapter;
        r.dailyLimit = dailyLimit;
        r.enabled = enabled;
        emit RouteSet(id, adapter, dailyLimit, enabled);
    }

    /// Any guardian (or governance) can stop all bridges at once.
    function pause() external {
        if (!guardian[msg.sender] && msg.sender != governance) revert NotGuardian();
        paused = true;
        emit Paused(msg.sender);
    }

    /// Restarting needs governance: a stolen guardian key can only stop things.
    function unpause() external onlyGov {
        paused = false;
        emit Unpaused();
    }

    function inbound(bytes32 id, address to, uint256 amount) external {
        Route storage r = _use(id, amount, true);
        r.inToday += uint128(amount);
        token.mint(to, amount);
        emit Inbound(id, to, amount);
    }

    function outbound(bytes32 id, address from, uint256 amount) external {
        Route storage r = _use(id, amount, false);
        r.outToday += uint128(amount);
        token.burn(from, amount);
        emit Outbound(id, from, amount);
    }

    function remaining(bytes32 id) external view returns (uint256 inLeft, uint256 outLeft) {
        Route storage r = routes[id];
        bool fresh = r.day != uint64(block.timestamp / 1 days);
        inLeft = r.dailyLimit - (fresh ? 0 : r.inToday);
        outLeft = r.dailyLimit - (fresh ? 0 : r.outToday);
    }

    function _use(bytes32 id, uint256 amount, bool isIn) private returns (Route storage r) {
        if (paused) revert BridgePaused();
        r = routes[id];
        if (!r.enabled || msg.sender != r.adapter) revert NotAdapter();
        uint64 today = uint64(block.timestamp / 1 days);
        if (r.day != today) { r.day = today; r.inToday = 0; r.outToday = 0; }
        uint256 used = isIn ? r.inToday : r.outToday;
        if (used + amount > r.dailyLimit) revert OverLimit(r.dailyLimit - used);
    }
}

contracts/ComputeMarket.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IRunnersView {
    function workers(address) external view returns (uint128 bond, uint64 unbondAt, bool active, uint32 agreed, uint32 rejected);
}

/// @title ComputeMarket: pay node runners in ZETAPHY for AI work (stage 4)
/// @notice Model output (tier 2+) is not deterministic, so it cannot be
///         settled by 2-of-3 agreement like Neuro tier 1. Instead: escrow.
///         The requester pays up front; a runner with a NeuroJobs track
///         record takes the task and delivers a result (hash + URI); the
///         requester accepts or rejects within REVIEW. Silence pays the
///         runner. Both sides' reject counts are public, so runners can avoid
///         requesters who reject everything, and requesters can avoid runners
///         who deliver junk.
contract ComputeMarket {
    uint64 public constant REVIEW = 1 days;

    enum Status { None, Open, Taken, Delivered, Paid, Refunded }

    struct Task {
        address requester;
        address runner;
        Status status;
        uint64 deadline;     // delivery due
        uint64 deliveredAt;
        bytes32 model;       // e.g. "llama-3.1-8b-instruct-q4"
        bytes32 inputHash;
        bytes32 resultHash;
        uint256 price;
        string inputURI;
        string resultURI;
    }

    IRunnersView public immutable runners;
    uint32 public immutable minAgreed;
    Task[] internal tasks;
    mapping(address => uint256) public credit;
    mapping(address => uint32) public runnerDone;
    mapping(address => uint32) public runnerRejected;
    mapping(address => uint32) public requesterRejections;

    event Requested(uint256 indexed id, bytes32 indexed model, uint256 price, uint64 deadline);
    event Taken(uint256 indexed id, address indexed runner);
    event Delivered(uint256 indexed id, bytes32 resultHash, string resultURI);
    event Settled(uint256 indexed id, Status status);

    error BadValue();
    error BadState();
    error NotAllowed();
    error TooEarly();
    error Nothing();

    constructor(IRunnersView runners_, uint32 minAgreed_) {
        runners = runners_;
        minAgreed = minAgreed_;
    }

    function request(bytes32 model, bytes32 inputHash, string calldata inputURI, uint64 seconds_) external payable returns (uint256 id) {
        if (msg.value == 0 || model == bytes32(0) || seconds_ == 0 || seconds_ > 7 days || bytes(inputURI).length > 256) revert BadValue();
        id = tasks.length;
        Task storage t = tasks.push();
        t.requester = msg.sender;
        t.status = Status.Open;
        t.deadline = uint64(block.timestamp) + seconds_;
        t.model = model;
        t.inputHash = inputHash;
        t.inputURI = inputURI;
        t.price = msg.value;
        emit Requested(id, model, msg.value, t.deadline);
    }

    function take(uint256 id) external {
        Task storage t = _task(id, Status.Open);
        (, , bool active, uint32 agreed, uint32 rejected) = runners.workers(msg.sender);
        if (!active || agreed < minAgreed || rejected > agreed || msg.sender == t.requester) revert NotAllowed();
        if (block.timestamp >= t.deadline) revert BadState();
        t.runner = msg.sender;
        t.status = Status.Taken;
        emit Taken(id, msg.sender);
    }

    function deliver(uint256 id, bytes32 resultHash, string calldata resultURI) external {
        Task storage t = _task(id, Status.Taken);
        if (msg.sender != t.runner) revert NotAllowed();
        if (block.timestamp > t.deadline || resultHash == bytes32(0) || bytes(resultURI).length > 256) revert BadValue();
        t.resultHash = resultHash;
        t.resultURI = resultURI;
        t.deliveredAt = uint64(block.timestamp);
        t.status = Status.Delivered;
        emit Delivered(id, resultHash, resultURI);
    }

    function accept(uint256 id) external {
        Task storage t = _task(id, Status.Delivered);
        if (msg.sender != t.requester) revert NotAllowed();
        _pay(id, t);
    }

    function reject(uint256 id) external {
        Task storage t = _task(id, Status.Delivered);
        if (msg.sender != t.requester) revert NotAllowed();
        if (block.timestamp > t.deliveredAt + REVIEW) revert BadState();
        runnerRejected[t.runner] += 1;
        requesterRejections[t.requester] += 1;
        _refund(id, t);
    }

    /// The runner is paid once the review window passes without a rejection.
    function claim(uint256 id) external {
        Task storage t = _task(id, Status.Delivered);
        if (block.timestamp <= t.deliveredAt + REVIEW) revert TooEarly();
        _pay(id, t);
    }

    /// Requester gets the money back if nobody took the task, or nothing was delivered in time.
    function cancel(uint256 id) external {
        if (id >= tasks.length) revert BadState();
        Task storage t = tasks[id];
        if (msg.sender != t.requester) revert NotAllowed();
        bool open = t.status == Status.Open;
        bool late = t.status == Status.Taken && block.timestamp > t.deadline;
        if (!open && !late) revert BadState();
        _refund(id, t);
    }

    function withdraw() external {
        uint256 a = credit[msg.sender];
        if (a == 0) revert Nothing();
        credit[msg.sender] = 0;
        (bool ok,) = msg.sender.call{value: a}("");
        require(ok, "transfer failed");
    }

    function taskCount() external view returns (uint256) { return tasks.length; }

    function getTask(uint256 id) external view returns (Task memory) {
        if (id >= tasks.length) revert BadState();
        return tasks[id];
    }

    function _task(uint256 id, Status want) private view returns (Task storage t) {
        if (id >= tasks.length) revert BadState();
        t = tasks[id];
        if (t.status != want) revert BadState();
    }

    function _pay(uint256 id, Task storage t) private {
        t.status = Status.Paid;
        credit[t.runner] += t.price;
        runnerDone[t.runner] += 1;
        emit Settled(id, Status.Paid);
    }

    function _refund(uint256 id, Task storage t) private {
        t.status = Status.Refunded;
        credit[t.requester] += t.price;
        emit Settled(id, Status.Refunded);
    }
}

contracts/NeuroJobs.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title NeuroJobs: the Neuro ZETAPHY job market (testnet, stage 1-2)
/// @notice Someone asks for a contract to be checked and pays a fee in ZETAPHY.
///         Up to three bonded node runners each compute Neuro's verdict on their
///         own machine. The verdict stands once two of them agree, and those two
///         share the fee plus a reward from the pool.
///
///         Commit-reveal stops a runner from copying another's answer: runners
///         first post keccak256(verdict, runner, salt), and reveal only after
///         all seats are taken or the commit window closes.
///
///         Payouts are credited, then pulled with withdraw() (no ETH is pushed
///         to arbitrary addresses inside the job logic).
contract NeuroJobs {
    uint8 public constant SEATS = 3;
    uint8 public constant QUORUM = 2;
    /// Share of the bond a runner loses for a verdict the quorum rejected,
    /// or for committing and then never revealing (basis points).
    uint16 public constant PENALTY_BPS = 1000;

    uint256 public immutable workerBond;
    uint256 public immutable jobReward;
    uint256 public immutable minFee;
    uint64 public immutable commitWindow;
    uint64 public immutable jobTimeout;
    uint64 public immutable unbondDelay;

    enum Status { None, Open, Done, Failed }

    struct Worker {
        uint128 bond;
        uint64 unbondAt; // 0 while active
        bool active;
        uint32 agreed;
        uint32 rejected;
    }

    struct Job {
        address requester;
        uint64 created;
        Status status;
        uint8 commits;
        uint8 reveals;
        bytes32 chain;
        uint256 fee;
        bytes32 result;
        string target;
        address[3] seat;
        bytes32[3] commitOf;
        bytes32[3] verdictOf;
        bool[3] revealed;
    }

    uint256 public rewardPool;
    uint256 public activeWorkers;
    mapping(address => Worker) public workers;
    mapping(address => uint256) public credit;
    Job[] internal jobs;

    event Funded(address indexed from, uint256 amount);
    event Registered(address indexed worker, uint256 bond);
    event UnbondRequested(address indexed worker, uint64 at);
    event JobRequested(uint256 indexed id, bytes32 indexed chain, string target, uint256 fee);
    event Committed(uint256 indexed id, address indexed worker);
    event Revealed(uint256 indexed id, address indexed worker, bytes32 verdict);
    event Finalized(uint256 indexed id, bytes32 verdict);
    event JobFailed(uint256 indexed id);
    event Penalized(address indexed worker, uint256 amount);

    error BadValue();
    error BadJob();
    error NotWorker();
    error Closed();
    error AlreadyIn();
    error NoSeat();
    error TooEarly();
    error BadReveal();
    error Nothing();

    constructor(uint256 bond_, uint256 reward_, uint256 minFee_, uint64 commitWindow_, uint64 timeout_, uint64 unbondDelay_) {
        if (bond_ == 0 || commitWindow_ == 0 || timeout_ <= commitWindow_ || unbondDelay_ < timeout_) revert BadValue();
        workerBond = bond_;
        jobReward = reward_;
        minFee = minFee_;
        commitWindow = commitWindow_;
        jobTimeout = timeout_;
        unbondDelay = unbondDelay_;
    }

    // ---- pool and runners ----

    function fund() external payable {
        if (msg.value == 0) revert BadValue();
        rewardPool += msg.value;
        emit Funded(msg.sender, msg.value);
    }

    function register() external payable {
        Worker storage w = workers[msg.sender];
        if (w.active) revert AlreadyIn();
        if (w.unbondAt != 0) revert TooEarly(); // finish leaving first
        uint256 bond = uint256(w.bond) + msg.value;
        if (bond < workerBond) revert BadValue();
        w.bond = uint128(bond);
        w.active = true;
        activeWorkers += 1;
        emit Registered(msg.sender, bond);
    }

    /// Leaving takes unbondDelay, so a runner cannot escape a penalty on a job
    /// it is still part of.
    function requestUnbond() external {
        Worker storage w = workers[msg.sender];
        if (!w.active) revert NotWorker();
        w.active = false;
        w.unbondAt = uint64(block.timestamp) + unbondDelay;
        activeWorkers -= 1;
        emit UnbondRequested(msg.sender, w.unbondAt);
    }

    function withdrawBond() external {
        Worker storage w = workers[msg.sender];
        if (w.active || w.unbondAt == 0 || block.timestamp < w.unbondAt) revert TooEarly();
        uint256 amount = w.bond;
        w.bond = 0;
        w.unbondAt = 0;
        credit[msg.sender] += amount;
    }

    function withdraw() external {
        uint256 amount = credit[msg.sender];
        if (amount == 0) revert Nothing();
        credit[msg.sender] = 0;
        (bool ok,) = msg.sender.call{value: amount}("");
        require(ok, "transfer failed");
    }

    // ---- jobs ----

    /// @param chain   chain key as bytes32, e.g. "bsc"
    /// @param target  address on that chain (EVM hex or Solana base58), at most 64 bytes
    function request(bytes32 chain, string calldata target) external payable returns (uint256 id) {
        return _request(msg.sender, chain, target);
    }

    /// Same as request(), but a refund goes to `refundTo`. Used by StableGateway,
    /// which pays the fee for a user who paid it in a stablecoin.
    function requestFor(address refundTo, bytes32 chain, string calldata target) external payable returns (uint256 id) {
        if (refundTo == address(0)) revert BadValue();
        return _request(refundTo, chain, target);
    }

    function _request(address requester, bytes32 chain, string calldata target) private returns (uint256 id) {
        if (msg.value < minFee || chain == bytes32(0) || bytes(target).length == 0 || bytes(target).length > 64) revert BadValue();
        id = jobs.length;
        Job storage j = jobs.push();
        j.requester = requester;
        j.created = uint64(block.timestamp);
        j.status = Status.Open;
        j.chain = chain;
        j.target = target;
        j.fee = msg.value;
        emit JobRequested(id, chain, target, msg.value);
    }

    /// @param commitment keccak256(abi.encode(verdict, msg.sender, salt))
    function commit(uint256 id, bytes32 commitment) external {
        Job storage j = _open(id);
        if (!workers[msg.sender].active) revert NotWorker();
        if (block.timestamp >= j.created + commitWindow || j.commits == SEATS) revert NoSeat();
        for (uint8 i = 0; i < j.commits; i++) if (j.seat[i] == msg.sender) revert AlreadyIn();
        j.seat[j.commits] = msg.sender;
        j.commitOf[j.commits] = commitment;
        j.commits += 1;
        emit Committed(id, msg.sender);
    }

    function reveal(uint256 id, bytes32 verdict, bytes32 salt) external {
        Job storage j = _open(id);
        if (j.commits < SEATS && block.timestamp < j.created + commitWindow) revert TooEarly();
        uint8 s = _seatOf(j, msg.sender);
        if (j.revealed[s]) revert AlreadyIn();
        if (keccak256(abi.encode(verdict, msg.sender, salt)) != j.commitOf[s]) revert BadReveal();
        j.revealed[s] = true;
        j.verdictOf[s] = verdict;
        j.reveals += 1;
        emit Revealed(id, msg.sender, verdict);

        // Quorum: this verdict matches QUORUM-1 earlier reveals.
        uint8 same = 0;
        for (uint8 i = 0; i < j.commits; i++) if (j.revealed[i] && j.verdictOf[i] == verdict) same++;
        if (same >= QUORUM) _finalize(id, j, verdict);
        else if (j.reveals == j.commits && (j.commits == SEATS || block.timestamp >= j.created + commitWindow)) {
            // Everyone who committed has revealed and no two agree.
            _fail(id, j, false);
        }
    }

    /// Anyone can close a job that ran out of time without a quorum.
    function expire(uint256 id) external {
        Job storage j = _open(id);
        if (block.timestamp < j.created + jobTimeout) revert TooEarly();
        _fail(id, j, true);
    }

    // ---- views ----

    function jobCount() external view returns (uint256) {
        return jobs.length;
    }

    function getJob(uint256 id) external view returns (
        address requester, uint64 created, Status status, bytes32 chain, string memory target,
        uint256 fee, bytes32 result, uint8 commits, uint8 reveals, address[3] memory seat
    ) {
        if (id >= jobs.length) revert BadJob();
        Job storage j = jobs[id];
        return (j.requester, j.created, j.status, j.chain, j.target, j.fee, j.result, j.commits, j.reveals, j.seat);
    }

    function seatOf(uint256 id, address worker) external view returns (bool seated, bool revealed_) {
        if (id >= jobs.length) revert BadJob();
        Job storage j = jobs[id];
        for (uint8 i = 0; i < j.commits; i++) if (j.seat[i] == worker) return (true, j.revealed[i]);
        return (false, false);
    }

    // ---- internals ----

    function _open(uint256 id) private view returns (Job storage j) {
        if (id >= jobs.length) revert BadJob();
        j = jobs[id];
        if (j.status != Status.Open) revert Closed();
    }

    function _seatOf(Job storage j, address w) private view returns (uint8) {
        for (uint8 i = 0; i < j.commits; i++) if (j.seat[i] == w) return i;
        revert NoSeat();
    }

    function _finalize(uint256 id, Job storage j, bytes32 verdict) private {
        j.status = Status.Done;
        j.result = verdict;
        uint8 winners = 0;
        for (uint8 i = 0; i < j.commits; i++) if (j.revealed[i] && j.verdictOf[i] == verdict) winners++;
        uint256 share = j.fee / winners;
        uint256 dust = j.fee - share * winners;
        for (uint8 i = 0; i < j.commits; i++) {
            address w = j.seat[i];
            if (j.revealed[i] && j.verdictOf[i] == verdict) {
                uint256 pay = share;
                if (rewardPool >= jobReward) { rewardPool -= jobReward; pay += jobReward; }
                credit[w] += pay;
                workers[w].agreed += 1;
            } else if (j.revealed[i]) {
                workers[w].rejected += 1;
                _penalize(w);
            }
            // A seat that has not revealed yet is judged when the job would
            // have timed out; after a quorum it simply earns nothing.
        }
        rewardPool += dust;
        emit Finalized(id, verdict);
    }

    function _fail(uint256 id, Job storage j, bool timedOut) private {
        j.status = Status.Failed;
        credit[j.requester] += j.fee;
        if (timedOut) {
            for (uint8 i = 0; i < j.commits; i++) if (!j.revealed[i]) _penalize(j.seat[i]);
        }
        emit JobFailed(id);
    }

    function _penalize(address w) private {
        Worker storage wk = workers[w];
        uint256 cut = (uint256(wk.bond) * PENALTY_BPS) / 10_000;
        if (cut == 0) return;
        wk.bond -= uint128(cut);
        rewardPool += cut;
        emit Penalized(w, cut);
        // Below the bond: stop taking new jobs until topped up.
        if (wk.active && wk.bond < workerBond) {
            wk.active = false;
            activeWorkers -= 1;
        }
    }
}

contracts/QuantumWallet.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title QuantumWallet: a smart wallet a quantum computer cannot drain (stage 5)
/// @notice Every action needs an ML-DSA signature (FIPS 204, post-quantum),
///         checked by ZETAPHY's precompile at 0x…0900. Two modes:
///           - hybrid: ECDSA AND ML-DSA must both sign (today's security, plus
///             protection if ECDSA is ever broken)
///           - post-quantum only: no ECDSA key at all (ecdsaOwner = 0)
///         Anyone may submit a signed action and pay its gas (a relay), so the
///         owner needs no other account. Keys rotate only through the wallet
///         itself, i.e. with the current keys' signatures.
contract QuantumWallet {
    address public constant MLDSA = 0x0000000000000000000000000000000000000900;

    address public ecdsaOwner;   // 0 = post-quantum only
    uint8 public variant;        // 44 or 65 (ML-DSA parameter set)
    bytes32 public pqKeyHash;    // keccak256 of the ML-DSA public key (the key itself rides in calldata)
    uint256 public nonce;

    /// The signatures for one action. pqPublicKey must hash to pqKeyHash;
    /// ecdsaSig is ignored in post-quantum-only mode.
    struct Auth {
        bytes pqPublicKey;
        bytes pqSig;
        bytes ecdsaSig;
    }

    event Executed(uint256 indexed nonce, address indexed to, uint256 value);
    event KeysChanged(address ecdsaOwner, uint8 variant, bytes32 pqKeyHash);

    error Expired();
    error BadEcdsa();
    error BadPq();
    error WrongKey();
    error BadVariant();
    error OnlySelf();
    error CallFailed(bytes reason);

    constructor(address ecdsaOwner_, uint8 variant_, bytes32 pqKeyHash_) payable {
        _setKeys(ecdsaOwner_, variant_, pqKeyHash_);
    }

    receive() external payable {}

    /// The 32 bytes both keys sign for one action.
    function digest(address to, uint256 value, bytes calldata data, uint256 deadline) public view returns (bytes32) {
        return keccak256(abi.encode("ZETAPHY QuantumWallet", block.chainid, address(this), nonce, to, value, keccak256(data), deadline));
    }

    function execute(address to, uint256 value, bytes calldata data, uint256 deadline, Auth calldata auth)
        external returns (bytes memory)
    {
        if (block.timestamp > deadline) revert Expired();
        _authorize(digest(to, value, data, deadline), auth);
        uint256 n = nonce++;
        (bool ok, bytes memory ret) = to.call{value: value}(data);
        if (!ok) revert CallFailed(ret);
        emit Executed(n, to, value);
        return ret;
    }

    function _authorize(bytes32 d, Auth calldata auth) private view {
        if (ecdsaOwner != address(0) && _recover(d, auth.ecdsaSig) != ecdsaOwner) revert BadEcdsa();
        if (keccak256(auth.pqPublicKey) != pqKeyHash) revert WrongKey();
        if (!_pqValid(d, auth.pqPublicKey, auth.pqSig)) revert BadPq();
    }

    /// Rotate keys or switch mode; callable only by execute() on this wallet.
    function setKeys(address ecdsaOwner_, uint8 variant_, bytes32 pqKeyHash_) external {
        if (msg.sender != address(this)) revert OnlySelf();
        _setKeys(ecdsaOwner_, variant_, pqKeyHash_);
    }

    function _setKeys(address ecdsaOwner_, uint8 variant_, bytes32 pqKeyHash_) private {
        if ((variant_ != 44 && variant_ != 65) || pqKeyHash_ == bytes32(0)) revert BadVariant();
        ecdsaOwner = ecdsaOwner_;
        variant = variant_;
        pqKeyHash = pqKeyHash_;
        emit KeysChanged(ecdsaOwner_, variant_, pqKeyHash_);
    }

    function _pqValid(bytes32 d, bytes calldata pk, bytes calldata sig) private view returns (bool) {
        (bool ok, bytes memory ret) = MLDSA.staticcall(abi.encodePacked(variant, d, pk, sig));
        return ok && ret.length == 32 && uint256(bytes32(ret)) == 1;
    }

    function _recover(bytes32 d, bytes calldata sig) private pure returns (address) {
        if (sig.length != 65) return address(0);
        bytes32 r = bytes32(sig[0:32]);
        bytes32 s = bytes32(sig[32:64]);
        uint8 v = uint8(sig[64]);
        if (uint256(s) > 0x7FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF5D576E7357A4501DDFE92F46681B20A0) return address(0);
        return ecrecover(d, v, r, s);
    }
}

/// @title QuantumWalletFactory: wallets at an address known before they exist
/// @notice The address depends only on the keys, so funds can be sent to a
///         wallet before it is deployed, and anyone can deploy it later.
contract QuantumWalletFactory {
    event Created(address indexed wallet, address ecdsaOwner, uint8 variant, bytes32 pqKeyHash);

    function create(address ecdsaOwner, uint8 variant, bytes32 pqKeyHash) external returns (address w) {
        w = address(new QuantumWallet{salt: _salt(ecdsaOwner, variant, pqKeyHash)}(ecdsaOwner, variant, pqKeyHash));
        emit Created(w, ecdsaOwner, variant, pqKeyHash);
    }

    function predict(address ecdsaOwner, uint8 variant, bytes32 pqKeyHash) external view returns (address) {
        bytes32 h = keccak256(abi.encodePacked(bytes1(0xff), address(this), _salt(ecdsaOwner, variant, pqKeyHash),
            keccak256(abi.encodePacked(type(QuantumWallet).creationCode, abi.encode(ecdsaOwner, variant, pqKeyHash)))));
        return address(uint160(uint256(h)));
    }

    function _salt(address e, uint8 v, bytes32 k) private pure returns (bytes32) {
        return keccak256(abi.encode(e, v, k));
    }
}

